import axios from 'axios';

export type AgentPayOptions = {
    /** e.g. http://localhost:3000 — `/v1` is appended automatically */
    baseUrl?: string;
    /** Optional bearer token sent to the backend */
    apiKey?: string;
};

function resolveBaseUrl(options?: AgentPayOptions): string {
    const raw =
        options?.baseUrl ??
        process.env.AGENTPAY_API_BASE_URL ??
        process.env.AGENTPAY_BACKEND_URL ??
        'http://localhost:3000';
    const trimmed = raw.replace(/\/$/, '');
    return trimmed.endsWith('/v1') ? trimmed : `${trimmed}/v1`;
}

export * from './x402';

export class AgentPay {
    private agentId: string;
    private baseURL: string;
    private apiKey?: string;

    constructor(agentId: string, options?: AgentPayOptions) {
        this.agentId = agentId;
        this.baseURL = resolveBaseUrl(options);
        this.apiKey = options?.apiKey;
    }

    async getWalletConnectStatus() {
        const headers = this.apiKey ? { Authorization: `Bearer ${this.apiKey}` } : undefined;
        const response = await axios.get(`${this.baseURL}/wc/status`, { headers });
        return response.data as import('./x402/types').WalletConnectStatus;
    }

    async payAndCall(serviceId: string, payload: unknown) {
        try {
            const headers = this.apiKey ? { Authorization: `Bearer ${this.apiKey}` } : undefined;
            const response = await axios.post(
                `${this.baseURL}/pay-and-call`,
                {
                    agentId: this.agentId,
                    serviceId,
                    payload
                },
                { headers }
            );
            return response.data;
        } catch (error: any) {
            const errMsg = error.response?.data?.error || error.message;
            console.error(`[SDK ERROR] ${errMsg}`);
            if (
                error.response?.status === 409 ||
                String(errMsg).includes('no active session')
            ) {
                throw new Error(
                    'WalletConnect session expired or not paired. User must open a new pairing link on their phone and tap Connect (Unstoppable Wallet). Agent: call get_pairing_link once, send the URL, then retry fetch_paid_service.'
                );
            }
            if (String(errMsg).includes('Invalid agent or service')) {
                throw new Error(
                    'Backend rejected pay-and-call: use AgentPay MCP tool fetch_paid_service (not direct /v1/pay-and-call). ' +
                        'Backend only accepts serviceId x402_custom for signing; Exa/Nansen/etc. are registry ids passed to fetch_paid_service.'
                );
            }
            return null;
        }
    }
}
